patches.before:
begin() {
	this.dispose();
	this.popup = window.open("about:blank", "_blank");
	if (this.popup) this.popup.opener = null;
}

patches.after:
begin() {
	this.dispose();
	// DSHA_NATIVE_OAUTH_NAVIGATION_V1: the native host consumes only the fixed
	// Platform authorize navigation, leaving this authenticated page alive.
	// No blank window is created: embedded engines cannot retain the Web
	// popup that the plain browser path preopens during the original click.
	if (globalThis.__DSHA_NATIVE_PLUGINS__ === true || globalThis.__DSHA_NATIVE_OAUTH__ === true) {
		const popup = {
			closed: false,
			close() { this.closed = true; },
			location: { replace(url) { if (!popup.closed) window.location.assign(url); } }
		};
		this.popup = popup;
		return;
	}
	this.popup = window.open("about:blank", "_blank");
	if (this.popup) this.popup.opener = null;
}
